values
  ('189ef8eb-270d-4538-9862-7032def36da0', 'd4e5f6a7-8b9c-4d71-8e01-1a2b3c4d5e11', null, 'topic'::public.curated_course_node_type, 'Assessment Literacy and Purposes of Assessment', 'This opening unit establishes assessment as a tool for improving learning, not merely judging it. Students learn to distinguish assessment purposes and to ask what evidence is needed for different instructional decisions.', 0),
  ('bcca2004-e500-4bbc-b8a0-4a7e69b1431a', 'd4e5f6a7-8b9c-4d71-8e01-1a2b3c4d5e11', '189ef8eb-270d-4538-9862-7032def36da0', 'subtopic'::public.curated_course_node_type, 'Purposes and users of assessment', 'Students learn that assessment design begins with the decision it is meant to inform.', 0),
  ('ff2c191d-87e5-432e-ada0-7861f04d4ad9', 'd4e5f6a7-8b9c-4d71-8e01-1a2b3c4d5e11', 'bcca2004-e500-4bbc-b8a0-4a7e69b1431a', 'concept'::public.curated_course_node_type, 'Assessment for, as, and of learning', null, 0),
