  ('cb647748-6461-4d98-8652-0b507f2d9648', 'd4e5f6a7-8b9c-4d71-8e01-1a2b3c4d5e11', 'dcdbbc81-85a4-420e-9ebd-e27915d2f4d6', 'concept'::public.curated_course_node_type, 'Coherence, redundancy, and assessment burden', null, 2),
  ('3c16e166-4f4c-4c90-8350-dc0ae40c497d', 'd4e5f6a7-8b9c-4d71-8e01-1a2b3c4d5e11', null, 'topic'::public.curated_course_node_type, 'Learning Targets, Standards, and Backward Design', 'Assessment quality depends on clarity about what students are supposed to learn. This unit connects standards, objectives, evidence, and instruction through backward design.', 1),
