  ('cacb523b-459b-4c86-ab8b-e3e4c6b05cc1', 'd4e5f6a7-8b9c-4d71-8e01-1a2b3c4d5e11', 'a61721d7-dfbc-4359-837b-897c5a76f39c', 'concept'::public.curated_course_node_type, 'Progression from novice to advanced performance', null, 2),
  ('d80c4f38-8615-4b5c-810d-6b39afa6dc5c', 'd4e5f6a7-8b9c-4d71-8e01-1a2b3c4d5e11', null, 'topic'::public.curated_course_node_type, 'Formative Assessment, Feedback, and Responsive Teaching', 'Formative assessment is a teaching practice, not a quiz type. Students learn to gather evidence during instruction and use it immediately to adjust teaching and support learner agency.', 2),
