  ('e42acc05-9abb-4f47-b45c-29e400f417f9', 'd4e5f6a7-8b9c-4d71-8e01-1a2b3c4d5e11', '4efb4345-d0c8-48bb-a3d5-658843d4a909', 'concept'::public.curated_course_node_type, 'Observation, conferences, and student work snapshots', null, 1),
