  ('0193902c-d603-4efe-badf-887d0880825b', 'd4e5f6a7-8b9c-4d71-8e01-1a2b3c4d5e11', '98e4d28a-0591-44db-b5b7-a2b96dce37b0', 'concept'::public.curated_course_node_type, 'Student self-monitoring and goal setting', null, 2),
  ('203f4307-7524-4a3c-b0d1-02e23ccb8cc7', 'd4e5f6a7-8b9c-4d71-8e01-1a2b3c4d5e11', null, 'topic'::public.curated_course_node_type, 'Summative Assessment Design and Test Construction', 'Summative assessments should provide credible evidence of learning after instruction. This unit teaches students to build assessments that are aligned, appropriately challenging, and interpretable.', 3);
