  ('e18ede12-5166-4c59-9fef-031672eb3a2f', 'd4e5f6a7-8b9c-4d71-8e01-1a2b3c4d5e11', '6d377038-0e50-47c0-aaa0-e26503134e87', 'concept'::public.curated_course_node_type, 'Analytic versus holistic scoring', null, 0),
