  ('cdce0152-8664-4b86-bb83-1aa66964846f', 'd4e5f6a7-8b9c-4d71-8e01-1a2b3c4d5e11', '25168510-63fc-4034-afb9-111911fe0d07', 'concept'::public.curated_course_node_type, 'Criteria aligned to learning targets', null, 0),
