update public.learning_paths
set
  title = 'Assessment of Learning',
  goal = 'Assessment of Learning',
  summary = 'This course prepares future educators to design, interpret, and use assessments that improve student learning. Students learn assessment literacy, standards alignment, formative assessment, summative assessment design, performance tasks, rubrics, portfolios, grading and reporting, data-driven instruction, standardized-test interpretation, fairness, accommodations, Universal Design for Learning, and assessment-system coherence. The course emphasizes evidence, equity, student agency, family communication, and responsible professional judgment.',
  data = $asoljson${"slug": "assessment-of-learning", "title": "Assessment of Learning", "description": "This course prepares future educators to design, interpret, and use assessments that improve student learning. Students learn assessment literacy, standards alignment, formative assessment, summative assessment design, performance tasks, rubrics, portfolios, grading and reporting, data-driven instruction, standardized-test interpretation, fairness, accommodations, Universal Design for Learning, and assessment-system coherence. The course emphasizes evidence, equity, student agency, family communication, and responsible professional judgment.", "topics": [{"id": "189ef8eb-270d-4538-9862-7032def36da0", "type": "topic", "title": "Assessment Literacy and Purposes of Assessment", "description": "This opening unit establishes assessment as a tool for improving learning, not merely judging it. Students learn to distinguish assessment purposes and to ask what evidence is needed for different instructional decisions.", "children": [{"id": "bcca2004-e500-4bbc-b8a0-4a7e69b1431a", "type": "subtopic", "title": "Purposes and users of assessment", "children": [{"id": "ff2c191d-87e5-432e-ada0-7861f04d4ad9", "type": "concept", "title": "Assessment for, as, and of learning"}, {"id": "ea3f0c35-9343-42dd-b91e-3245bd0a27d1", "type": "concept", "title": "Students, teachers, families, schools, and systems as users"}, {"id": "117a2b64-a63a-46f5-9137-1f699bfd120f", "type": "concept", "title": "Instructional, grading, placement, accountability, and program decisions"}], "description": "Students learn that assessment design begins with the decision it is meant to inform."}, {"id": "381fe135-2818-4aba-a6bd-06caf6e079e5", "type": "subtopic", "title": "Assessment literacy", "children": [{"id": "a7814f57-173f-4413-9bfb-ecd045e50ead", "type": "concept", "title": "Validity, reliability, fairness, and usability"}, {"id": "17d357a2-0d8d-4c97-9f6e-e9606dcf0228", "type": "concept", "title": "Evidence, inference, and consequences"}, {"id": "b8cf8b60-32cb-47d0-b60d-df40cbd3ca8a", "type": "concept", "title": "Teacher professional judgment and documentation"}], "description": "Students build the vocabulary and judgment needed to create and evaluate classroom assessments."}, {"id": "dcdbbc81-85a4-420e-9ebd-e27915d2f4d6", "type": "subtopic", "title": "Balanced assessment systems", "children": [{"id": "a8c79a89-3d4c-45bd-b6e3-f9c9bbe0a097", "type": "concept", "title": "Formative, interim, summative, diagnostic, and benchmark assessments"}, {"id": "77db23f6-77b9-4346-baf1-43b209fb39fa", "type": "concept", "title": "Classroom, school, district, and state assessment roles"}, {"id": "cb647748-6461-4d98-8652-0b507f2d9648", "type": "concept", "title": "Coherence, redundancy, and assessment burden"}], "description": "Students see how no single assessment can serve every purpose well."}]}, {"id": "3c16e166-4f4c-4c90-8350-dc0ae40c497d", "type": "topic", "title": "Learning Targets, Standards, and Backward Design", "description": "Assessment quality depends on clarity about what students are supposed to learn. This unit connects standards, objectives, evidence, and instruction through backward design.", "children": [{"id": "4f86018a-c5d8-46b0-b5ee-7464b3414f2b", "type": "subtopic", "title": "Unpacking standards and learning goals", "children": [{"id": "97e09e0e-8db3-4883-a169-318b7d721eb5", "type": "concept", "title": "Knowledge, reasoning, skill, product, and disposition targets"}, {"id": "6424876e-2361-48d0-8c73-c5a94d2c0b79", "type": "concept", "title": "Standards, competencies, and learning progressions"}, {"id": "fcc4d646-d005-4e75-be2e-7f6668b2cea0", "type": "concept", "title": "Common Core, NGSS, state standards, and local curriculum"}], "description": "Students learn to translate broad standards into teachable and assessable targets."}, {"id": "d22c51e1-d5d6-4c07-89bb-2efbee8ed7cd", "type": "subtopic", "title": "Backward design", "children": [{"id": "b37bbe6c-24d3-4e69-ac05-c5b42441d696", "type": "concept", "title": "Desired results, acceptable evidence, and learning plan"}, {"id": "ac632494-8202-404c-95af-96baddc7d359", "type": "concept", "title": "Transfer, understanding, and essential questions"}, {"id": "7ce1923b-3456-4da5-9faf-3908be98c7ed", "type": "concept", "title": "Alignment among goals, assessment, and instruction"}], "description": "Students learn to plan assessment evidence before selecting activities."}, {"id": "a61721d7-dfbc-4359-837b-897c5a76f39c", "type": "subtopic", "title": "Success criteria and learning progressions", "children": [{"id": "6a9e17d3-fda5-45ee-af0b-ce4bd1bdeba9", "type": "concept", "title": "Student-friendly learning targets"}, {"id": "f02e76f4-431b-48c3-98c7-4d162b728950", "type": "concept", "title": "Criteria for proficiency"}, {"id": "cacb523b-459b-4c86-ab8b-e3e4c6b05cc1", "type": "concept", "title": "Progression from novice to advanced performance"}], "description": "Students learn to make quality visible to learners."}]}, {"id": "d80c4f38-8615-4b5c-810d-6b39afa6dc5c", "type": "topic", "title": "Formative Assessment, Feedback, and Responsive Teaching", "description": "Formative assessment is a teaching practice, not a quiz type. Students learn to gather evidence during instruction and use it immediately to adjust teaching and support learner agency.", "children": [{"id": "4efb4345-d0c8-48bb-a3d5-658843d4a909", "type": "subtopic", "title": "Eliciting evidence of learning", "children": [{"id": "e1234eb2-c640-430e-a7a4-928d384bbd88", "type": "concept", "title": "Questioning, hinge questions, exit tickets, whiteboards, and retrieval checks"}, {"id": "e42acc05-9abb-4f47-b45c-29e400f417f9", "type": "concept", "title": "Observation, conferences, and student work snapshots"}, {"id": "0aa02e17-a54c-4d7e-ab0d-fa55f7defb44", "type": "concept", "title": "Misconception detection and error analysis"}], "description": "Students learn fast, purposeful ways to see student thinking while instruction is still flexible."}, {"id": "9664863d-8c56-4714-9a20-d2d5a2fd9eb7", "type": "subtopic", "title": "Feedback that moves learning forward", "children": [{"id": "cf121e76-d91b-49bb-a315-2ab6a7b2cc44", "type": "concept", "title": "Task, process, and self-regulation feedback"}, {"id": "abf7298c-f3b1-499f-bee0-fdb1536c3426", "type": "concept", "title": "Avoiding vague praise and grade-only feedback"}, {"id": "40088105-dbd3-4046-b752-dbba2bfcc856", "type": "concept", "title": "Feedback cycles and opportunities to revise"}], "description": "Students learn to give feedback that is timely, specific, usable, and focused on improvement."}, {"id": "98e4d28a-0591-44db-b5b7-a2b96dce37b0", "type": "subtopic", "title": "Responsive instruction", "children": [{"id": "5e90293f-00db-435f-b2ac-91b7f8ce8499", "type": "concept", "title": "Reteaching, grouping, enrichment, and intervention"}, {"id": "152161ad-cf20-42b0-8833-96c94f09b631", "type": "concept", "title": "Adjusting pacing and scaffolds"}, {"id": "0193902c-d603-4efe-badf-887d0880825b", "type": "concept", "title": "Student self-monitoring and goal setting"}], "description": "Students learn to convert assessment evidence into instructional action."}]}, {"id": "203f4307-7524-4a3c-b0d1-02e23ccb8cc7", "type": "topic", "title": "Summative Assessment Design and Test Construction", "description": "Summative assessments should provide credible evidence of learning after instruction. This unit teaches students to build assessments that are aligned, appropriately challenging, and interpretable.", "children": [{"id": "f26f90b6-7fa3-47b4-8be2-8935c71c097a", "type": "subtopic", "title": "Assessment blueprints", "children": [{"id": "59e5d4bf-81af-4d0b-aeaa-5bdeca3b0963", "type": "concept", "title": "Content domains and cognitive demand"}, {"id": "6baa87b9-cb5f-428c-8f02-82920eb52629", "type": "concept", "title": "Weighting targets and item/task types"}, {"id": "99b421a5-3d9e-44e3-8169-6898e16f62c6", "type": "concept", "title": "Depth of knowledge and alignment checks"}], "description": "Students learn to plan coverage before writing items or tasks."}, {"id": "1c0f6e4b-d042-4c0a-9879-c83b12bca7ed", "type": "subtopic", "title": "Item and task design", "children": [{"id": "e06a84ee-a421-4fb8-94f5-f04734a2a78d", "type": "concept", "title": "Multiple-choice and matching item principles"}, {"id": "019f354c-1c3f-4bfb-a1f0-70c37d2062a6", "type": "concept", "title": "Short answer, constructed response, and prompts"}, {"id": "fdfdc2d4-56ef-488c-b80f-676e0155a699", "type": "concept", "title": "Distractors, cueing, ambiguity, and accessibility"}], "description": "Students learn to write selected-response, constructed-response, and short-performance items that measure the intended target."}, {"id": "f625e1ce-d449-4ad6-b7e8-0b6222b445f3", "type": "subtopic", "title": "Quality control", "children": [{"id": "b883a7b7-6fdb-4a6e-837c-fb6a3c08edbf", "type": "concept", "title": "Validity evidence and construct representation"}, {"id": "426c2c61-7a09-4132-a1f3-2ddbaf697912", "type": "concept", "title": "Reliability, consistency, and scoring clarity"}, {"id": "2249b0d0-edfb-4126-ae23-b4873b69dc5e", "type": "concept", "title": "Piloting, item review, and revision"}], "description": "Students learn how assessment evidence can be strengthened before use."}]}, {"id": "140a4a56-5592-4644-afc0-d8d8b197bee5", "type": "topic", "title": "Performance-Based Assessment and Authentic Tasks", "description": "Performance assessments ask students to use learning in meaningful contexts. This unit helps students design tasks that reveal transfer, reasoning, process, and product quality.", "children": [{"id": "51c13f40-1df7-49e9-8263-7274562b9332", "type": "subtopic", "title": "Authentic performance tasks", "children": [{"id": "b5598dbe-8fb6-4c65-be67-4085e32bbff4", "type": "concept", "title": "Realistic context, audience, purpose, and constraints"}, {"id": "77d7f60b-3e8b-4253-a988-16d223151de9", "type": "concept", "title": "Transfer and application"}, {"id": "b83bc2b9-1c66-47b7-8bdd-75bebffce4fe", "type": "concept", "title": "Product, performance, process, and reflection evidence"}], "description": "Students learn what makes a task worth doing and assessable."}, {"id": "956644c3-62d1-4920-8488-d08a9b7d60b2", "type": "subtopic", "title": "Project-based and inquiry assessment", "children": [{"id": "89c65879-a80b-4caa-979e-bc1afad8f036", "type": "concept", "title": "Milestones and checkpoints"}, {"id": "bd7575c6-dc46-4034-9ea7-47b935042aa4", "type": "concept", "title": "Collaboration and individual accountability"}, {"id": "ccc6fdf1-05a4-472e-bc96-f5a9f0b0c8d9", "type": "concept", "title": "Inquiry products, presentations, and exhibitions"}], "description": "Students learn to assess complex learning without losing clarity."}, {"id": "03d2135a-44eb-4fef-99e2-ab612c6a1b78", "type": "subtopic", "title": "Scaffolding complex tasks", "children": [{"id": "fb37eb18-0876-416c-ac8b-de134531fc59", "type": "concept", "title": "Models and exemplars"}, {"id": "5b65f8a5-65ab-4f9b-aa8c-d199f8aabb05", "type": "concept", "title": "Checklists, planning tools, and conferences"}, {"id": "9bdafe11-b2d3-4e43-9c62-74417153e626", "type": "concept", "title": "Accessibility supports and gradual release"}], "description": "Students learn to support success while preserving rigor."}]}, {"id": "c43922a7-203a-4702-bfbf-086ec1f6873c", "type": "topic", "title": "Rubrics, Scoring Criteria, and Rater Judgment", "description": "Rubrics make expectations visible and scoring more consistent, but only when they are well designed. Students learn to write criteria that describe quality rather than count superficial features.", "children": [{"id": "6d377038-0e50-47c0-aaa0-e26503134e87", "type": "subtopic", "title": "Rubric types and purposes", "children": [{"id": "e18ede12-5166-4c59-9fef-031672eb3a2f", "type": "concept", "title": "Analytic versus holistic scoring"}, {"id": "70ebc7eb-42e0-498b-a705-bea6e323796d", "type": "concept", "title": "Single-point rubrics and feedback"}, {"id": "33d47c90-9bb5-4988-9ad9-4699af51f106", "type": "concept", "title": "Checklists versus rubrics"}], "description": "Students learn when to use analytic, holistic, single-point, and developmental rubrics."}, {"id": "25168510-63fc-4034-afb9-111911fe0d07", "type": "subtopic", "title": "Writing quality criteria", "children": [{"id": "cdce0152-8664-4b86-bb83-1aa66964846f", "type": "concept", "title": "Criteria aligned to learning targets"}, {"id": "4af62c01-4284-43fc-915a-2ec265f84e83", "type": "concept", "title": "Level descriptors and progression"}, {"id": "b87108c3-1264-4f15-a5b8-456437621097", "type": "concept", "title": "Avoiding deficit language and hidden bias"}], "description": "Students learn to define performance levels in observable, growth-oriented language."}, {"id": "2d8e94f2-f5fe-4725-8c85-00b92ff30951", "type": "subtopic", "title": "Calibration and scoring consistency", "children": [{"id": "0c26b424-f306-4a99-81a5-6b2bb5202c68", "type": "concept", "title": "Anchor papers and exemplars"}, {"id": "1024963c-de15-4770-a4fc-8d0fffc792cb", "type": "concept", "title": "Moderation and norming protocols"}, {"id": "acdfd508-1cdc-4eff-b539-a42715bc40fb", "type": "concept", "title": "Inter-rater reliability and scoring drift"}], "description": "Students learn how teachers improve scoring judgment with shared evidence."}]}, {"id": "3e524627-552a-4031-9831-4fba0d727c62", "type": "topic", "title": "Portfolios, Student Self-Assessment, and Metacognition", "description": "Assessment can help students understand their own learning. This unit treats portfolios and self-assessment as tools for metacognition, growth, and ownership.", "children": [{"id": "14cef3f6-c857-4e09-bf2f-d90b7ff9d950", "type": "subtopic", "title": "Portfolio design", "children": [{"id": "cc38541f-c24b-4959-9dd1-7fcfb0b91bcc", "type": "concept", "title": "Working, showcase, and growth portfolios"}, {"id": "22390425-cfe8-4bce-bfe7-09ed2a30e42b", "type": "concept", "title": "Artifact selection and reflection"}, {"id": "ceae8eff-2b14-4189-8a3b-fe003adb6ee0", "type": "concept", "title": "Digital portfolios and privacy"}], "description": "Students learn to organize evidence of learning across time."}, {"id": "fe58b07b-1db0-4efa-b13e-b51b4acbc347", "type": "subtopic", "title": "Self-assessment and goal setting", "children": [{"id": "2c10ae43-283b-4786-8b4d-566dba406e27", "type": "concept", "title": "Student-friendly rubrics"}, {"id": "520aabed-7dd2-4bb3-a5fc-254e3448a30a", "type": "concept", "title": "Reflection prompts and learning logs"}, {"id": "7f39d570-fb39-462b-8f9f-7f2200444c28", "type": "concept", "title": "Goal cycles and progress monitoring"}], "description": "Students learn how students can evaluate their work against criteria."}, {"id": "ee25f95e-5dbe-4f82-961c-976ba4b35fec", "type": "subtopic", "title": "Peer assessment and conferences", "children": [{"id": "e52c3245-cc2f-4897-808c-3c4234e2bbdc", "type": "concept", "title": "Peer critique norms and protocols"}, {"id": "a467ddea-de4e-42e0-ad5c-565a212efdda", "type": "concept", "title": "Student-led conferences"}, {"id": "85fc577f-eb97-4437-b567-0985f8148c97", "type": "concept", "title": "Teacher facilitation and evidence curation"}], "description": "Students learn to structure peer feedback and family-facing conversations productively."}]}, {"id": "86a1609c-9e19-4647-8873-549276d39307", "type": "topic", "title": "Grading, Reporting, and Standards-Based Communication", "description": "Grading is one of the most consequential uses of assessment. Students learn to separate evidence of learning from behavior, compliance, timing, and opportunity differences.", "children": [{"id": "fecf762c-4dfa-4fc7-8700-eef7b6f06abd", "type": "subtopic", "title": "Purposes and problems of grades", "children": [{"id": "d6cf7f22-fbc9-46a0-8fb6-5e76f46e348c", "type": "concept", "title": "Achievement, growth, effort, behavior, and completion"}, {"id": "592a142c-fd88-4125-bfc8-61e944b020ff", "type": "concept", "title": "Averaging, zeros, late work, and retakes"}, {"id": "251d2886-32db-4732-85db-88dc7b871e36", "type": "concept", "title": "Motivation, identity, and opportunity effects"}], "description": "Students examine what grades communicate and where they can distort learning."}, {"id": "2b364947-f994-41f4-8f2e-8559fd6f1aaa", "type": "subtopic", "title": "Standards-based and equitable grading", "children": [{"id": "c0845a63-db61-48d5-8680-96db885a1bc6", "type": "concept", "title": "Proficiency scales and evidence by standard"}, {"id": "6727d042-20c6-4df4-82ff-4ea5e6fd87d3", "type": "concept", "title": "Reassessment and most-recent evidence"}, {"id": "b69f69ef-5213-4e02-9bb8-78b9dc804b3e", "type": "concept", "title": "Equity-centered grading principles"}], "description": "Students learn alternatives that better communicate mastery."}, {"id": "3c2418a7-5679-40f4-a9a6-58972e5236f4", "type": "subtopic", "title": "Reporting to families and students", "children": [{"id": "d0c1548a-fc14-4dad-8871-c51758ec9e78", "type": "concept", "title": "Narrative feedback and progress reports"}, {"id": "3ad855bc-2d8b-47b2-8420-081c98b2354b", "type": "concept", "title": "Student/family conferences"}, {"id": "066e2e05-211a-4689-aadc-7599d943725c", "type": "concept", "title": "Actionable next steps and strengths-based language"}], "description": "Students learn to communicate assessment information clearly and constructively."}]}, {"id": "99938104-c62b-42c0-bc21-286a0993f569", "type": "topic", "title": "Data-Driven Instruction and Learning Analytics", "description": "Assessment data are useful only when interpreted carefully and connected to instruction. This unit teaches students to use data cycles without reducing learners to numbers.", "children": [{"id": "9130fd77-88af-4837-b913-afa4d52a1e6e", "type": "subtopic", "title": "Classroom data analysis", "children": [{"id": "3dc8edbc-16ec-4b5f-8bf5-19f5d7fef99e", "type": "concept", "title": "Item analysis and error patterns"}, {"id": "d7d1e28b-5b6b-4873-9ed2-42996e2021d0", "type": "concept", "title": "Standards-level performance"}, {"id": "d6c3b44d-e714-45d4-90fc-0ecdfd668fc5", "type": "concept", "title": "Small-group and individual needs"}], "description": "Students learn practical ways to turn student work and scores into instructional insights."}, {"id": "e93261ed-057b-432d-8c79-6077e638d0b1", "type": "subtopic", "title": "Data cycles and team routines", "children": [{"id": "f9a4a811-a5f1-4628-ba2f-148794b430b8", "type": "concept", "title": "Plan-teach-assess-reflect cycles"}, {"id": "21eafc55-e9c4-420c-8012-04ca3686848d", "type": "concept", "title": "PLC data conversations"}, {"id": "093144ed-27bd-4c10-80de-1f0df066297d", "type": "concept", "title": "Root-cause analysis and action planning"}], "description": "Students learn collaborative structures for evidence-based improvement."}, {"id": "b9f6b3ae-953e-47d4-8b2f-6ae4edb69f96", "type": "subtopic", "title": "Progress monitoring and intervention", "children": [{"id": "4526a9c0-9f7a-4fae-ac5d-01bc8f77044c", "type": "concept", "title": "Screening, diagnostic assessment, and monitoring"}, {"id": "11cf7196-2e29-49eb-a6b7-7041a7680bc6", "type": "concept", "title": "MTSS/RTI connections"}, {"id": "1bc26591-6d78-4c01-8035-1dd0ca42bdd1", "type": "concept", "title": "Intervention goals and decision rules"}], "description": "Students learn how assessment supports tiered instruction and follow-up."}]}, {"id": "545ccf95-63c0-4892-82c3-7f7847c23875", "type": "topic", "title": "Standardized Testing, Accountability, and Interpretation", "description": "Teachers need to understand standardized tests even when they do not control them. This unit helps students interpret scores, communicate limits, and resist misuse.", "children": [{"id": "e3a7a835-76b0-4d52-a080-74d4be8b47a1", "type": "subtopic", "title": "Types of standardized assessments", "children": [{"id": "fe14ebde-78b4-4a97-be31-40dbd3979673", "type": "concept", "title": "Norm-referenced and criterion-referenced tests"}, {"id": "fbf72ee4-db11-426f-8b65-bc28c503e88b", "type": "concept", "title": "Percentiles, scale scores, proficiency levels, and growth scores"}, {"id": "45c50ecc-80d8-4d5e-aedb-bcb69f4a8a25", "type": "concept", "title": "State assessments, benchmarks, and screeners"}], "description": "Students learn the major categories and interpretations of large-scale testing."}, {"id": "c6149ebf-6062-4f3f-b8df-de1c936b2615", "type": "subtopic", "title": "Accountability and consequences", "children": [{"id": "5e1312c1-1784-4062-aba2-886d3f742f8d", "type": "concept", "title": "School accountability metrics"}, {"id": "1e7c20a5-a020-45ae-bf71-d3e57c2219b1", "type": "concept", "title": "Test preparation and curriculum narrowing"}, {"id": "f51b6b87-679f-446a-829f-b6a08e6360aa", "type": "concept", "title": "High-stakes consequences and unintended effects"}], "description": "Students examine how assessment systems influence curriculum, instruction, and equity."}, {"id": "037af5e8-55d5-48a2-a9b8-cd06a3ac3ab4", "type": "subtopic", "title": "Ethical interpretation", "children": [{"id": "2a92c4f4-46ac-4f64-ae6e-6a29fd301145", "type": "concept", "title": "Measurement error and confidence bands"}, {"id": "427cce9d-a7d9-4355-b235-09e0651082cd", "type": "concept", "title": "Multiple measures and triangulation"}, {"id": "4c10337d-9e13-4364-ac77-0b7bde7d67be", "type": "concept", "title": "Avoiding deficit interpretations"}], "description": "Students learn to communicate test information accurately and cautiously."}]}, {"id": "c8069209-dec3-4f1f-94a9-f7f0c9949e7d", "type": "topic", "title": "Fairness, Bias, Accommodations, and Inclusive Assessment", "description": "A world-class assessment course must center fairness. This unit teaches students to design assessments that preserve the construct while reducing barriers unrelated to the learning target.", "children": [{"id": "bcffa098-f84c-4688-bdd2-15b10487d319", "type": "subtopic", "title": "Bias and fairness", "children": [{"id": "572f5d2a-ef95-4bb4-af3c-7bb747ead921", "type": "concept", "title": "Content, language, cultural, and format bias"}, {"id": "96c106c4-8b76-40ca-a66a-e8fdb572b549", "type": "concept", "title": "Opportunity to learn"}, {"id": "e1549253-3949-4f53-80b6-7dc6bbd0b1f4", "type": "concept", "title": "Differential access to background knowledge and resources"}], "description": "Students learn to identify how assessment can advantage or disadvantage students."}, {"id": "86686631-1aed-42d4-b44d-6b2d36cfe1ad", "type": "subtopic", "title": "Accommodations and accessibility", "children": [{"id": "e4d07b81-c5d6-4ff2-92f6-5fae4a777c2a", "type": "concept", "title": "IEP, 504, and multilingual learner accommodations"}, {"id": "b56b0677-daff-4ce5-a2da-704e751cdad7", "type": "concept", "title": "Construct-relevant versus construct-irrelevant supports"}, {"id": "2b5693de-6579-4ceb-a32b-0137eaed0b5a", "type": "concept", "title": "Assistive technology and accessible formats"}], "description": "Students learn to support students without changing what is being measured."}, {"id": "6f9e3147-3ef2-4ac9-ab2e-6d915973de97", "type": "subtopic", "title": "Universal Design for Learning in assessment", "children": [{"id": "32976986-0e17-4a9d-a95e-e869e03418ba", "type": "concept", "title": "Multiple means of engagement"}, {"id": "0d94e195-6f82-47b5-9333-3f37fec957df", "type": "concept", "title": "Multiple means of representation"}, {"id": "12b49cdd-d842-4b7c-9827-3716025131fd", "type": "concept", "title": "Multiple means of action and expression"}], "description": "Students learn to design flexible assessment pathways from the start."}]}, {"id": "f22352ae-1b49-47ed-848a-7f007ebc2864", "type": "topic", "title": "Assessment Systems, Program Evaluation, and Professional Practice", "description": "The capstone unit asks students to synthesize assessment as a professional practice. Students build a coherent assessment portfolio and learn to evaluate assessment systems beyond a single classroom task.", "children": [{"id": "5c7332ce-55e3-45b6-9829-969782334aeb", "type": "subtopic", "title": "Coherent assessment systems", "children": [{"id": "4bbab0c4-d5cc-40cd-abad-ccd7fbb0b3e9", "type": "concept", "title": "Assessment maps and calendars"}, {"id": "15666402-bf97-4879-9af6-bd7535b14236", "type": "concept", "title": "Balanced evidence across targets"}, {"id": "7c8d390c-12a4-4cd6-9dc8-45df20f1e64f", "type": "concept", "title": "Reducing assessment overload"}], "description": "Students learn to align classroom assessment with curriculum, instruction, intervention, and reporting."}, {"id": "f0b83543-15b7-489b-94f6-a253f0092238", "type": "subtopic", "title": "Evaluation and improvement", "children": [{"id": "37270f39-3431-4212-b3a4-78614ecb0b40", "type": "concept", "title": "Logic models and outcome measures"}, {"id": "5bf81c32-8436-4df2-bd33-e9bd678dcb7f", "type": "concept", "title": "Implementation fidelity"}, {"id": "733de73d-9e74-4ba4-893a-cf3c788c12ee", "type": "concept", "title": "Evaluation reports and recommendations"}], "description": "Students learn how assessment evidence informs program and instructional improvement."}, {"id": "a93dda35-e829-4777-ae99-22d82c3feb48", "type": "subtopic", "title": "Professional ethics and portfolio defense", "children": [{"id": "d8d5238b-84a8-4c16-8786-701418d9d973", "type": "concept", "title": "Validity argument for an assessment set"}, {"id": "7b13acd3-aeb9-4f8a-b734-93f7e2ead487", "type": "concept", "title": "Evidence of fairness and accessibility"}, {"id": "c06f83bc-26ab-4292-b9a3-2a3c43916393", "type": "concept", "title": "Reflection on teacher judgment and next steps"}], "description": "Students demonstrate assessment literacy through a defensible final portfolio."}]}], "dbBacked": true}$asoljson$::jsonb,
